.rocket-wrap { position: relative; width: 100%; height: 300vh; }
#rocket-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.rocket-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.rocket-msg {
  position: absolute; color: white; font-size: 35px; font-weight: 900; text-align: center;
  opacity: 0; transition: opacity 0.5s; text-shadow: 0 5px 15px rgba(0,0,0,0.8);
}

jsCode:
const mc = document.getElementById('container');
mc.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#0b0e14;position:relative;';

mc.innerHTML = `
  <div class="rocket-wrap">
    <canvas id="rocket-canvas"></canvas>
    <div class="rocket-text-layer">
      <div id="r1" class="rocket-msg" style="font-size:20px; top:80%; color:#aaa;">Launch on Scroll ↓</div>
      <div id="r2" class="rocket-msg" style="color:#ffaa00;">LEAVING ORBIT</div>
      <div id="r3" class="rocket-msg" style="font-size:50px; color:#00d2ff;">DEEP SPACE</div>
    </div>
  </div>
`;

const rCvs = document.getElementById('rocket-canvas');
const rCtx = rCvs.getContext('2d');
let rW, rH;
let smoke = [], stars = [];

function initRocket() {
  rW = rCvs.width = window.innerWidth;
  rH = rCvs.height = window.innerHeight;
  stars = [];
  for(let i=0; i<200; i++) stars.push({x: Math.random()*rW, y: Math.random()*rH, size: Math.random()*2});
}
initRocket(); window.addEventListener('resize', initRocket);

let rProg = 0;
mc.addEventListener('scroll', () => {
  rProg = mc.scrollTop / (mc.scrollHeight - mc.clientHeight);
  document.getElementById('r1').style.opacity = (rProg < 0.1) ? 1 : 0;
  document.getElementById('r2').style.opacity = (rProg > 0.3 && rProg < 0.6) ? 1 : 0;
  document.getElementById('r3').style.opacity = (rProg > 0.8) ? 1 : 0;
});

function drawRocket() {
  rCtx.fillStyle = `rgba(11, 14, 20, ${1 - rProg})`; // સ્ક્રોલ સાથે બેકગ્રાઉન્ડ ઘેરો કાળો (Space) થશે
  rCtx.fillRect(0,0,rW,rH);

  // તારાઓ (Stars) બતાવવા
  if (rProg > 0.2) {
    stars.forEach(s => {
      rCtx.beginPath(); rCtx.arc(s.x, s.y, s.size, 0, Math.PI*2);
      rCtx.fillStyle = `rgba(255, 255, 255, ${(rProg - 0.2) * 1.5})`; rCtx.fill();
    });
  }

  // રોકેટની સ્થિતિ (Position)
  let rocketX = rW / 2;
  let rocketY = rH - (rProg * rH * 1.2); 

  // રોકેટનો ધુમાડો (Smoke Particles)
  if (rProg > 0 && rProg < 0.9) {
    smoke.push({x: rocketX + (Math.random()-0.5)*10, y: rocketY + 20, life: 1, vx: (Math.random()-0.5)*2});
  }

  for (let i = smoke.length - 1; i >= 0; i--) {
    let s = smoke[i];
    s.life -= 0.02; s.x += s.vx; s.y += 2;
    if (s.life <= 0) { smoke.splice(i, 1); continue; }
    rCtx.beginPath(); rCtx.arc(s.x, s.y, s.life * 15, 0, Math.PI*2);
    rCtx.fillStyle = `rgba(255, 100, 0, ${s.life})`; rCtx.fill();
  }

  // રોકેટ દોરવું (Emoji)
  if (rProg < 0.95) {
    rCtx.font = '50px sans-serif';
    rCtx.textAlign = 'center'; rCtx.textBaseline = 'middle';
    rCtx.fillText('🚀', rocketX, rocketY);
  }

  requestAnimationFrame(drawRocket);
}
drawRocket();
